effect.shader:
vec3 u_xlat0;
vec3 u_xlat1;
bvec3 u_xlatb1;
mediump float u_xlat16_2;
void main()
{
    u_xlat0.xyz = vec3(_color_picker_h) * vec3(6.0, 6.0, 6.0) + vec3(0.0, 4.0, 2.0);
    u_xlat0.xyz = u_xlat0.xyz * vec3(0.166666672, 0.166666672, 0.166666672);
    u_xlatb1.xyz = greaterThanEqual(u_xlat0.xyzx, (-u_xlat0.xyzx)).xyz;
    u_xlat0.xyz = fract(abs(u_xlat0.xyz));
    {
        vec3 hlslcc_movcTemp = u_xlat0;
        hlslcc_movcTemp.x = (u_xlatb1.x) ? u_xlat0.x : (-u_xlat0.x);
        hlslcc_movcTemp.y = (u_xlatb1.y) ? u_xlat0.y : (-u_xlat0.y);
        hlslcc_movcTemp.z = (u_xlatb1.z) ? u_xlat0.z : (-u_xlat0.z);
        u_xlat0 = hlslcc_movcTemp;
    }
    u_xlat0.xyz = u_xlat0.xyz * vec3(6.0, 6.0, 6.0) + vec3(-3.0, -3.0, -3.0);
    u_xlat0.xyz = abs(u_xlat0.xyz) + vec3(-1.0, -1.0, -1.0);
    u_xlat0.xyz = clamp(u_xlat0.xyz, 0.0, 1.0);
    u_xlat1.xyz = u_xlat0.xyz * u_xlat0.xyz;
    u_xlat1.xyz = u_xlat0.xyz * u_xlat1.xyz;
    u_xlat0.xyz = (-u_xlat0.xyz) * vec3(2.0, 2.0, 2.0) + vec3(3.0, 3.0, 3.0);
    u_xlat0.xyz = u_xlat1.xyz * u_xlat0.xyz + vec3(-1.0, -1.0, -1.0);
    u_xlat0.xyz = acScreenNorm.xxx * u_xlat0.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat16_2 = (-acScreenNorm.y) + 1.0;
    u_xlat16_2 = u_xlat16_2 * -4.1844244;
    u_xlat16_2 = exp2(u_xlat16_2);
    u_xlat0.xyz = u_xlat0.xyz * vec3(u_xlat16_2);
    u_xlat1.xyz = u_xlat0.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat1.xyz = u_xlat0.xyz * u_xlat1.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    fragColor.xyz = u_xlat0.xyz * u_xlat1.xyz;
    fragColor.w = 1.0;
    return;
}
